/**
 * Settings -> Abilities & commands (the owner's requirement of 2026-10-22,
 * Gemini Q2/Q8): one directory/search that indexes every feature and says,
 * for each one, which of exactly five plain labels it is - and, where it is
 * not a switch, that honestly, with an example phrase and the screen path.
 *
 * WHERE THE WORDS COME FROM. Nothing here is typed by hand or guessed from
 * prose: `feature-directory.js` is GENERATED by
 * `tools/gen_feature_directory.py` from the canonical, checked
 * `contract/feature-controls.json` (schema 1, 139 features). That contract is
 * lock-hook's cross-surface classification, joined with voiceprint-wiring's
 * command-side matrix; its own checker runs the real intent matcher on every
 * example phrase and fails on a missing label. A missing contract fails this
 * module's generator loudly; it never defaults a row.
 *
 * THIS IS AN INDEX, NOT A SECOND SETTINGS SURFACE. There is no button, toggle,
 * checkbox or select in the list, and nothing here calls the PC. A switchable
 * row says which existing Settings card changes it; a Command-Only row says
 * what to ask for and where; an Always-On row says it is a rule rather than a
 * setting. The interactive things are the filter box - which only hides rows
 * locally (no setting is changed, and clearing it restores every row) - and the
 * five native `<details>` disclosures the five labels are grouped under. There
 * is no button, toggle, checkbox or select inside the directory.
 *
 * The rows are in the page's text, not drawn later on demand, so the Settings
 * search box (settings-search.js) indexes all 139 features as words on screen.
 *
 * @module feature-directory-ui
 */

import { FEATURE_DIRECTORY } from "./feature-directory.js";

const $ = (id) => document.getElementById(id);
// The five owner-approved labels, in the owner's order. The generated file
// carries them (it validates them against the canonical contract), so this
// module never repeats the strings: a changed label is a regeneration, not an
// edit here.
const LABEL_ORDER = Array.isArray(FEATURE_DIRECTORY.label_order)
  ? FEATURE_DIRECTORY.label_order : Object.keys(FEATURE_DIRECTORY.labels);

const el = {
  list: $("fd-list"),
  legend: $("fd-legend"),
  count: $("fd-count"),
  filter: $("fd-filter"),
};

const norm = (s) => String(s || "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();

let rows = [];

function rowWords(row) {
  return norm([row.title, row.group, row.label, row.example, row.where_desktop,
    row.where_phone, row.note].join(" "));
}

function rowNode(row) {
  const li = document.createElement("li");
  li.className = "fd-row";
  li.dataset.fdRow = "true";
  li.dataset.fdId = row.id;

  const title = document.createElement("h3");
  title.className = "fd-name";
  title.textContent = row.title;
  li.append(title);

  if (row.status === "planned" || row.status === "pc-only") {
    const badge = document.createElement("span");
    badge.className = "fd-badge";
    badge.textContent = row.status === "planned" ? "Planned" : "PC only";
    li.append(badge);
  }

  const label = document.createElement("p");
  label.className = "fd-label";
  label.textContent = row.label;
  li.append(label);

  const example = document.createElement("p");
  example.className = "note fd-example";
  if (row.status === "planned") {
    // A planned row has no proved typed phrase yet. Showing "Try: ..." would
    // invite the owner to try words that do not change that feature.
    example.textContent = "Typed phrase: planned - not wired yet.";
  } else if (row.status === "pc-only") {
    example.textContent = row.example_ok
      ? `Try on this PC: "${row.example}"`
      : "PC only: no fixed typed phrase yet.";
  } else {
    example.textContent = `Try: "${row.example}"`;
  }
  li.append(example);

  const where = document.createElement("p");
  where.className = "note fd-where";
  where.textContent = row.where_desktop === row.where_phone
    ? `Where: ${row.where_desktop}`
    : `On this PC: ${row.where_desktop} · On the phone: ${row.where_phone}`;
  li.append(where);

  if (row.note) {
    const note = document.createElement("p");
    note.className = "note fd-note";
    note.textContent = row.note;
    li.append(note);
  }
  return li;
}

function renderLegend(counts) {
  if (!el.legend) return;
  el.legend.textContent = "";
  for (const label of LABEL_ORDER) {
    const item = document.createElement("p");
    item.className = "note fd-legend-line";
    item.textContent = `${label} — ${FEATURE_DIRECTORY.labels[label]} ` +
      `(${counts.get(label) || 0})`;
    el.legend.append(item);
  }
}

function render(filter = "") {
  if (!el.list) return;
  const words = norm(filter).split(" ").filter(Boolean);
  const counts = new Map();
  for (const row of rows) {
    counts.set(row.label, (counts.get(row.label) || 0) + 1);
  }
  renderLegend(counts);
  el.list.textContent = "";
  let shown = 0;
  for (const label of LABEL_ORDER) {
    const groupRows = rows.filter((row) => row.label === label &&
      (!words.length || words.every((w) => rowWords(row).includes(w))));
    if (!groupRows.length) continue;
    const fold = document.createElement("details");
    fold.className = "fd-group";
    fold.open = words.length > 0;
    const summary = document.createElement("summary");
    summary.className = "fd-group-title";
    summary.textContent = `${label} (${groupRows.length})`;
    fold.append(summary);
    const ul = document.createElement("ul");
    ul.className = "fd-rows";
    for (const row of groupRows) ul.append(rowNode(row));
    fold.append(ul);
    el.list.append(fold);
    shown += groupRows.length;
  }
  if (el.count) {
    el.count.textContent = `${shown} of ${rows.length} abilities and commands`;
  }
}

if (el.list && FEATURE_DIRECTORY && Array.isArray(FEATURE_DIRECTORY.rows)) {
  rows = FEATURE_DIRECTORY.rows;
  render();
  el.filter?.addEventListener("input", () => render(el.filter.value));
  el.filter?.addEventListener("search", () => render(el.filter.value));
} else if (el.count) {
  el.count.textContent = "The list of abilities could not be loaded.";
}
